"""Dataset catalogue: what each known scientific dataset is, where it comes from and how it is accessed.

This file DESCRIBES datasets (source, nominal resolution, CRS, units, access route). It contains no
measurements. Nominal resolutions are product-level figures; always confirm against the downloaded
product's own metadata. On hackathon day add rows here (or upload files in the Data Sources panel)
and the registry picks them up automatically.

provenance classes used across the app:
  real         downloaded/fetched from a public scientific service at run time
  local        supplied by the user (upload or storage/ directory)
  demonstration  hand-compiled or synthetic values that only exercise the workflow
  derived      computed by this application from the inputs above
"""
from __future__ import annotations

PROVENANCE_CLASSES = {
    "real": "Real data fetched from a public service",
    "local": "Locally supplied by the user",
    "demonstration": "Synthetic or hand-compiled demonstration values",
    "derived": "Derived or model-generated by this application",
}

